/// Frozen predecessor shapes from `.scratch/pacta-planning-20261115/r3-migration-matrix.md`.
///
/// Every historical table below is a literal transcript of the schema generated by
/// `git show <commit>:lib/src/tasks/task_database.dart` at the fixed commit: the
/// columns are the ones that existed there, in the generated order, with the same
/// nullability, defaults and CHECK constraints. Nothing here is "current schema plus
/// a stamped user_version": a shape is built by replacing the tables that gained
/// columns later with these historical statements and dropping the tables that did
/// not exist yet, then asserting the resulting structure equals the recorded
/// historical inventory before any row is written.
class PredecessorShape {
  const PredecessorShape({
    required this.label,
    required this.commits,
    required this.userVersion,
    this.absentTables = const <String>[],
    this.missingColumns = const <String, List<String>>{},
    this.historicalDdl = const <String, String>{},
  });

  /// Short label used in test names and temp directory names.
  final String label;

  /// Fixed commits that produced this exact structure.
  final List<String> commits;

  final int userVersion;

  /// Tables that did not exist in this shape.
  final List<String> absentTables;

  /// Columns that did not exist yet, per table that did exist.
  final Map<String, List<String>> missingColumns;

  /// Historical CREATE TABLE text for every table this shape had in an older form.
  final Map<String, String> historicalDdl;

  bool hadTable(String table) => !absentTables.contains(table);

  bool hadColumn(String table, String column) {
    final missing = missingColumns[table];
    return missing == null || !missing.contains(column);
  }
}

