// ---------------------------------------------------------------------------
// Fixture builder.
// ---------------------------------------------------------------------------

/// A file-backed historical database, built from the frozen DDL above.
class PredecessorFixture {
  PredecessorFixture({
    required this.shape,
    required this.directory,
    required this.file,
  });

  final PredecessorShape shape;
  final Directory directory;
  final File file;

  /// The first connection opened after [buildPredecessorFixture]; migrations run
  /// on first use.
  PactaDatabase open() => PactaDatabase(NativeDatabase(file));

  Future<void> dispose() async {
    try {
      await directory.delete(recursive: true);
    } on FileSystemException {
      // A leaked handle on Windows keeps the temp directory; the OS cleans it.
    }
  }
}

/// Builds a real historical database for [shape]: historical DDL, seeded rows,
/// and the shape's own user_version. Never touches a user or default Pacta DB.
Future<PredecessorFixture> buildPredecessorFixture(
  PredecessorShape shape,
) async {
  final directory = await Directory.systemTemp.createTemp('pacta-pre-');
  final file = File('${directory.path}${Platform.pathSeparator}pacta.sqlite');
  final database = PactaDatabase(NativeDatabase(file));
  try {
    // Force onCreate, then record the current structure as the reference the
    // historical shape is measured against.
    await database.select(database.localGoals).get();
    final currentTables = await _tableNames(database);
    final currentColumns = <String, List<String>>{
      for (final table in currentTables)
        table: await _columnNames(database, table),
    };

    for (final table in shape.absentTables) {
      await database.customStatement('DROP TABLE "$table"');
    }
    for (final entry in shape.historicalDdl.entries) {
      await database.customStatement('DROP TABLE "${entry.key}"');
      await database.customStatement(entry.value);
    }

    await _verifyHistoricalStructure(
      database,
      shape: shape,
      currentTables: currentTables,
      currentColumns: currentColumns,
    );
    await _seed(database, shape);
    await database.customStatement(
      'PRAGMA user_version = ${shape.userVersion}',
    );
  } finally {
    await database.close();
  }
  return PredecessorFixture(shape: shape, directory: directory, file: file);
}

Future<void> _verifyHistoricalStructure(
  PactaDatabase database, {
  required PredecessorShape shape,
  required Set<String> currentTables,
  required Map<String, List<String>> currentColumns,
}) async {
  final expectedTables = currentTables.difference(shape.absentTables.toSet());
  final actualTables = await _tableNames(database);
  if (!_sameSet(actualTables, expectedTables)) {
    throw StateError(
      '表结构不是 ${shape.label} 的历史形状。期望 ${(expectedTables.toList()..sort()).join(',')} 实际 ${(actualTables.toList()..sort()).join(',')}',
    );
  }
  for (final table in expectedTables) {
    final missing = shape.missingColumns[table] ?? const <String>[];
    final expected = currentColumns[table]!
        .where((column) => !missing.contains(column))
        .toList();
    final actual = await _columnNames(database, table);
    if (expected.join(',') != actual.join(',')) {
      throw StateError(
        '列结构不是 ${shape.label} 的历史形状：$table 期望 ${expected.join(',')} 实际 ${actual.join(',')}',
      );
    }
  }
}

bool _sameSet(Set<String> left, Set<String> right) =>
    left.length == right.length && left.containsAll(right);

Future<Set<String>> _tableNames(PactaDatabase database) async {
  final rows = await database
      .customSelect(
        "SELECT name FROM sqlite_master WHERE type = 'table' AND name NOT LIKE 'sqlite_%'",
      )
      .get();
  return <String>{for (final row in rows) row.read<String>('name')};
}

Future<List<String>> _columnNames(PactaDatabase database, String table) async {
  final rows = await database.customSelect('PRAGMA table_info("$table")').get();
  return <String>[for (final row in rows) row.read<String>('name')];
}

int _epoch(DateTime value) => value.toUtc().millisecondsSinceEpoch ~/ 1000;

/// Seeds representative rows for two users, written only into columns the shape
/// actually has. Nothing is written into a later column, so retention after the
/// upgrade is real retention.
Future<void> _seed(PactaDatabase database, PredecessorShape shape) async {
  final createdAt = DateTime.utc(2026, 11, 10, 1);
  final updatedAt = DateTime.utc(2026, 11, 12, 2);
  final deletedAt = DateTime.utc(2026, 11, 13, 3);
  final startsAt = DateTime.utc(2026, 11, 16, 1);
  final endsAt = DateTime.utc(2026, 11, 16, 2);
  final checkpointAt = DateTime.utc(2026, 11, 14, 0);

  Future<void> insert(String table, Map<String, Object?> values) async {
    if (!shape.hadTable(table)) return;
    final columns = await _columnNames(database, table);
    final present = values.keys.where(columns.contains).toList();
    final sql =
        'INSERT INTO "$table" (${present.map((column) => '"$column"').join(', ')}) VALUES (${List.filled(present.length, '?').join(', ')})';
    await database.customStatement(sql, <Object?>[
      for (final column in present) values[column],
    ]);
  }

  for (final user in <String>['user-a', 'user-b']) {
    final suffix = user == 'user-a' ? 'a' : 'b';
    await insert('local_goals', <String, Object?>{
      'user_id': user,
      'id': 'goal-$suffix',
      'title': '目标$suffix',
      'description': '描述$suffix',
      'classification': 'regular',
      'created_at': _epoch(createdAt),
      'updated_at': _epoch(updatedAt),
      'deleted_at': null,
      // Non-default pins for the two shapes that already have the columns
      // (b9b9b38 schema 35, 51a5af7 schema 37); the insert helper drops them for
      // shapes that predate the columns.
      'is_pinned': 1,
      'sort_order': user == 'user-a' ? 1 : 0,
    });
    await insert('local_tasks', <String, Object?>{
      'user_id': user,
      'id': 'task-$suffix',
      'goal_id': 'goal-$suffix',
      'title': '任务$suffix',
      'description': '任务说明$suffix',
      'classification': 'regular',
      'estimated_minutes': 45,
      'deadline': _epoch(startsAt),
      'is_complete': 1,
      'focus_progress_seconds': 120,
      'created_at': _epoch(createdAt),
      'updated_at': _epoch(updatedAt),
      'deleted_at': null,
    });
    await insert('focus_appointments', <String, Object?>{
      'user_id': user,
      'id': 'appointment-$suffix',
      'task_id': 'task-$suffix',
      'mode': 'regular',
      'duration_seconds': 1800,
      'started_at': _epoch(startsAt),
      'ends_at': _epoch(endsAt),
      'status': 'active',
      'settled_at': null,
      'session_id': null,
      'failure_reason': null,
      'updated_at': _epoch(updatedAt),
      'review_disposition': 'accepted',
      'review_disposition_updated_at': null,
      'configuration_basis_source_id': null,
      'preparation_seconds': 420,
    });
    await insert('local_profile_accounts', <String, Object?>{
      'user_id': user,
      'display_name': '用户$suffix',
      'avatar_mime_type': null,
      'avatar_bytes': null,
      'pending_save': 0,
      'sync_error': null,
      'updated_at': _epoch(updatedAt),
      'edit_sequence': 3,
      'time_zone_id': 'Asia/Shanghai',
      'time_zone_revision': 7,
      'pending_time_zone_upload': 1,
    });
    await insert('local_national_focus_failures', <String, Object?>{
      'user_id': user,
      'id': 'failure-$suffix',
      'batch_id': 'batch-$suffix',
      'card_id': 'card-$suffix',
      'checkpoint_at': _epoch(checkpointAt),
      'cause': 'missed_confirmation',
      'failure_reason': '原因$suffix',
      'shared_explanation': null,
      'tree_snapshot': '[]',
      'review_disposition': 'accepted',
      'reviewed_at': _epoch(checkpointAt.add(const Duration(hours: 5))),
    });
  }

  // A goal tombstone and one reviewed failure stay visible to retention checks.
  await insert('local_goals', <String, Object?>{
    'user_id': 'user-a',
    'id': 'goal-deleted',
    'title': '已删除目标',
    'description': '',
    'classification': 'elite',
    'created_at': _epoch(createdAt),
    'updated_at': _epoch(updatedAt),
    'deleted_at': _epoch(deletedAt),
    // A pinned tombstone keeps its pin and its manual position.
    'is_pinned': 1,
    'sort_order': 0,
  });

  if (!shape.hadTable('local_schedules')) {
    // The 29 / schedule-less 30 shapes own legacy calendar blocks that the merge
    // promotes exactly once.
    for (final user in <String>['user-a', 'user-b']) {
      final suffix = user == 'user-a' ? 'a' : 'b';
      await insert('local_calendar_sources', <String, Object?>{
        'user_id': user,
        'source_id': 'calendar-1',
        'display_name': '工作',
        'time_zone_id': 'Asia/Shanghai',
        'local_calendar_id': null,
        'is_selected': 1,
        'is_stale': 0,
        'is_deleted': 0,
        'updated_at': _epoch(updatedAt),
      });
      await insert('local_calendar_blocks', <String, Object?>{
        'user_id': user,
        'source_id': 'calendar-1',
        'source_event_id': 'event-1',
        'occurrence_id': 'event-1:20261116',
        'event_identity': 'event-1:20261116',
        'title': '周会$suffix',
        'starts_at': _epoch(startsAt),
        'ends_at': _epoch(endsAt),
        'all_day': 0,
        'all_day_start_date': null,
        'all_day_end_date_exclusive': null,
        'availability': 'busy',
        'time_zone_id': 'Asia/Shanghai',
        'updated_at': _epoch(updatedAt),
      });
    }
    return;
  }

  // Owned, imported, recurring, exception and cancelled-tombstone schedules.
  for (final user in <String>['user-a', 'user-b']) {
    final suffix = user == 'user-a' ? 'a' : 'b';
    final base = <String, Object?>{
      'user_id': user,
      'notes': '备注$suffix',
      'starts_at': _epoch(startsAt),
      'ends_at': _epoch(endsAt),
      'all_day': 0,
      'all_day_start_date': null,
      'all_day_end_date_exclusive': null,
      'is_completed': 1,
      'completed_at': _epoch(endsAt),
      'task_id': 'task-$suffix',
      'reminder_minutes_before': 15,
      'origin': 'owned',
      'source_ids': '[]',
      'source_names': '[]',
      'source_event_id': null,
      'occurrence_id': null,
      'event_identity': null,
      'recurrence_id': null,
      'recurrence_series_id': null,
      'recurrence_date': null,
      'recurrence_time_zone_id': null,
      'recurrence_start_minutes': null,
      'is_recurrence_exception': 0,
      'is_recurrence_cancelled': 0,
      'created_at': _epoch(createdAt),
      'updated_at': _epoch(updatedAt),
    };
    await insert('local_schedules', <String, Object?>{
      ...base,
      'id': 'schedule-owned-$suffix',
      'title': '自有日程$suffix',
    });
    await insert('local_schedules', <String, Object?>{
      ...base,
      'id': 'schedule-imported-$suffix',
      'title': '导入日程$suffix',
      'notes': '',
      'is_completed': 0,
      'completed_at': null,
      'reminder_minutes_before': null,
      'origin': 'calendarImport',
      'source_ids': '["calendar-1"]',
      'source_names': '["工作"]',
      'source_event_id': 'event-imported',
      'occurrence_id': 'event-imported:20261116',
      'event_identity': 'event-imported:20261116',
    });
  }

  // Instances need the recurrence columns on the schedule row; the rule table
  // itself is a separate later structure.
  if (shape.hadColumn('local_schedules', 'recurrence_id')) {
    for (final user in <String>['user-a', 'user-b']) {
      final suffix = user == 'user-a' ? 'a' : 'b';
      for (final id in <String>[
        'schedule-series-$suffix',
        'schedule-exception-$suffix',
        'schedule-cancelled-$suffix',
      ]) {
        await insert('local_schedules', <String, Object?>{
          'user_id': user,
          'id': id,
          'title': id.contains('exception')
              ? '仅本次改写$suffix'
              : id.contains('cancelled')
              ? '已取消这一期$suffix'
              : '系列日程$suffix',
          'notes': id.contains('series') ? '系列备注$suffix' : '例外备注$suffix',
          'starts_at': _epoch(startsAt),
          'ends_at': _epoch(endsAt),
          'all_day': 0,
          'all_day_start_date': null,
          'all_day_end_date_exclusive': null,
          'is_completed': 0,
          'completed_at': null,
          'task_id': id.contains('series') ? 'task-$suffix' : null,
          'reminder_minutes_before': id.contains('series') ? 5 : null,
          'origin': 'owned',
          'source_ids': '[]',
          'source_names': '[]',
          'source_event_id': null,
          'occurrence_id': null,
          'event_identity': null,
          'recurrence_id': 'rule-fresh-$suffix',
          'recurrence_series_id': 'series-fresh-$suffix',
          'recurrence_date': '2026-11-16',
          'recurrence_time_zone_id': 'Asia/Shanghai',
          'recurrence_start_minutes': 540,
          'is_recurrence_exception': id.contains('exception') ? 1 : 0,
          'is_recurrence_cancelled': id.contains('cancelled') ? 1 : 0,
          'created_at': _epoch(createdAt),
          'updated_at': _epoch(updatedAt),
        });
      }
    }
  }

  if (!shape.hadTable('local_schedule_recurrences')) {
    return;
  }

  for (final user in <String>['user-a', 'user-b']) {
    final suffix = user == 'user-a' ? 'a' : 'b';
    // rule-fresh has no content template in shapes that predate it, so the
    // upgrade must backfill it from the earliest non-exception instance.
    await insert('local_schedule_recurrences', <String, Object?>{
      'user_id': user,
      'id': 'rule-fresh-$suffix',
      'frequency': 'daily',
      'weekdays': '[]',
      'first_date': '2026-11-16',
      'end_date': null,
      'time_zone_id': 'Asia/Shanghai',
      'all_day': 0,
      'start_minutes_of_day': 540,
      'duration_minutes': 60,
      'day_span': 1,
      'shift_days': 0,
      'title': '',
      'notes': '',
      'task_id': null,
      'reminder_minutes_before': null,
      'created_at': _epoch(createdAt),
      'updated_at': _epoch(updatedAt),
    });
    // rule-kept already carries non-default template values. The upgrade must not
    // rewrite them, and must not copy an instance reminder into the rule.
    await insert('local_schedule_recurrences', <String, Object?>{
      'user_id': user,
      'id': 'rule-kept-$suffix',
      'frequency': 'weekly',
      'weekdays': '[1,4]',
      'first_date': '2026-11-16',
      'end_date': '2026-12-28',
      'time_zone_id': 'Asia/Shanghai',
      'all_day': 0,
      'start_minutes_of_day': 600,
      'duration_minutes': 45,
      'day_span': 1,
      'shift_days': 3,
      'title': '已有模板$suffix',
      'notes': '模板备注$suffix',
      'task_id': 'task-$suffix',
      'reminder_minutes_before': 45,
      'created_at': _epoch(createdAt),
      'updated_at': _epoch(updatedAt),
    });
  }
}
